using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle;

internal sealed class FirstNegativeShiftExchangeDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native prefix truncation, actual even-half insertion or relocation, and odd-parent prefix insertion construct full physical strict J competitors in complementary first-negative regions.",
        H("First negative omission and actual inverse-parent exchanges"),
        Blocks(
            Describe.Lean(DescribeId.Create("native-three-negative-first-negative-shift-exchange"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FirstNegativeShiftExchange.actualSource_threeNegative_firstNegative_shift_exchange_full"),
                H("Full physical exchange retaining every SMALL occurrence"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("The exchange is conditional on the two actual old arrival measurements stated below. It reuses native_geometry, strip_split, inStrip_append, exists_order_between and inventory_of_perm. The new construction joins the complete T0++T1 batch across the omitted first negative and checks the two retained negative gates at their translated actual endpoints.")),
                    Paragraph(Text("For arbitrary k>=3 and natural t, use physical labels Fin k and the full centered dyadic source s(k,t). Put Q=2^(k-2), N=4Q-1, C=2Q-1, n=rho(p), x=rho(n), P=s(p)>0, D=abs(s(n)), r=abs(s(x)). Assume n is LARGE and N<3P. Native geometry proves s(n)=-D, s(x)=r, Q<=D<P<r<=C, D=N-2P, r=2P-D and 2P<=C+Q. The actual old word W=A++[x]++T0++[y]++T1++[zpen]++T2++[z]++E is Legal from ORIGINAL zero, with all natural takes and physical Nodup. Both p and n are unused in all W. A is arbitrary; every occurrence of S=T0++T1++T2++E is SMALL, with abs(s(i))<Q. The three physical occurrences y,zpen,z are negative LARGE. No numerical-source injectivity is assumed.")),
                    Paragraph(Text("Write Y=-s(y), a0=sum(A), h=sum(W). Assume C-P<h<D and Y<=P. The two additional measurements are the actual old prefix sums AFTER zpen and AFTER z, each >=C-P. Explicitly they are sum(A++[x]++T0++[y]++T1++[zpen]) and sum(A++[x]++T0++[y]++T1++[zpen]++T2++[z]). These are not sums of suffixes and are not shifted or reordered measurements. Equality with C-P is allowed. The theorem adds no q, a, crossing-band or source-edge premise, no Bad-count premise and no Z<=D premise. It does not assume a new Legal word or an available return batch.")),
                    Paragraph(Text("Set delta=Y-P<=0 and b=a0+P-D. Old legality at the physical x gives a0>=0 and a0+r<=C. Thus [p,n] is legal at a0, including its intermediate arrival a0+P; its final height is b in [0,C-P], hence in [0,Q-1]. Let d1,a1 be the old departure and arrival of zpen, and d2,a2 those of z. All four are in [0,C], and a1<=d1, a2<=d2. For each measured arrival a, a+delta>=C+Y-2P>=C+Q-2P>=0. The shifted departures are no lower than the corresponding shifted arrivals; all four shifted heights are <=C because delta<=0. This verifies the retained LARGE gates separately, even if their magnitudes exceed D.")),
                    Paragraph(Text("The first COMPLETE batch is T0++T1. Its required endpoints are b and d1+delta, and b+sum(T0++T1)=d1+delta follows exactly from r=2P-D and Y=-s(y). It joins across the omitted FIRST y. One must not translate the intermediate old T0 or T1 prefixes blindly. The next complete batch T2 runs from a1+delta to d2+delta, and the complete final E runs from a2+delta to e0=h+Y-P. Both identities use their full actual old prefixes. The blocking inequalities give e0>C+Y-2P>=0 and e0<D+Y-P<Y<=P<=C, so e0 is strictly interior.")),
                    Paragraph(Text("For two opposite SMALL entries i,j, integer strictness gives s(i)-s(j)<=2Q-2<C=2Q-1. Thus exists_order_between applies to EACH complete batch, including empty batches, producing L01.Perm(T0++T1), L2.Perm(T2), LE.Perm(E), with every intermediate height checked at its respective required start. The literal new suffix is L=L01++[zpen]++L2++[z]++LE, and the literal new full word is V=A++[p,n]++L. The proof assembles these strips using inStrip_append, keeping A from its original zero. It obtains InStrip(V), physical Nodup and Legal(V), together with every natural take, including zero and overlength takes. The retained zpen,z remain in that order and y is the first occurrence omitted, regardless of which negative magnitude is largest.")),
                    Paragraph(Text("Complete-batch permutations give (L++[y]).Perm(T0++[y]++T1++[zpen]++T2++[z]++E) and the exact whole-word permutation (V++[x,y]).Perm(W++[p,n]). inventory_of_perm supplies exact disjoint used and complementary unused partitions, source balance and physical Nodup. It also verifies that x,y are actually absent from V and that zpen,z are present. All S and every old SMALL in A remain; no SMALL occurrence is returned. The full physical source, not a proper subset, has total zero. Consequently sum(V)=e0 and remainingMass(V)=-e0.")),
                    Paragraph(Text("Both inserted p,n and returned x,y are LARGE. Thus G(V)=G(W), U(V)=U(W), and remainingSmall(V)=remainingSmall(W). The exact natural-number identity is H(V)+3^abs(s(x))+3^abs(s(y))=H(W)+3^abs(s(p))+3^abs(s(n)). Native expanding-path energy gives 3^P+3^D<3^r; the returned y term further increases the removed energy. It follows that H(V)<H(W) and J(V)<J(W), with no truncated subtraction or change to the frozen definitions of G,H,U,J.")),
                    Paragraph(Text("This remains the dedicated all-SMALL-retaining branch result. The arrival-free theorem below handles low old arrivals by literal prefix truncations with strict G descent, and invokes this theorem only when both actual arrivals exceed C-P. It does not assert uniform SMALL retention for those truncations. Numerical ties remain distinct physical labels. The even-half and odd-parent results below cover further first-Y>P regions; the remaining placements and full original-quantifier Circle C3.1 remain open. Four-slot escape registration is unfinished under https://github.com/the-omega-institute/trureturing/issues/22063: faithful complete-telescope source reconstruction, lawful enrolled readout and whole-family variation, sensitivity and observational-dependence evidence have not been established."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-prefix-pair-truncation"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FirstNegativeShiftExchange.actualSource_prefix_pair_truncation"),
                H("Consumed native low-prefix pair construction"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For arbitrary natural k,t with k>=3, p:Fin k and physical lists F,R, put n=rho(p), W=F++R and V=F++[p,n]. Assume P=s(k,t,p)>0, Q<=abs(s(k,t,n)), N<3*abs(s(k,t,p)), Legal(k,t,W), both p,n unused in ALL W, sum(F)<=C-P and largeUsed(k,t,R)<=1. R may contain SMALL occurrences. These are the complete hypotheses. The theorem returns Legal(V), Inventory(k,t,W,V,[p,n],R), (V++R).Perm(W++[p,n]), G(V)+2=G(W)+largeUsed(R), G(V)<G(W) and J(V)<J(W).")),
                    Paragraph(Text("native_geometry gives s(n)=-D, D<P and both inserted labels LARGE. strip_split retains the complete old F from ORIGINAL zero and gives 0<=v=sum(F). The two literal new arrivals are v+P and v+P-D, both in [0,C], using v<=C-P and D<P. inStrip_append assembles V. Distinctness and whole-W unusedness of p,n, plus the full-word permutation, feed inventory_of_perm; its physical Nodup, exact used/unused disjoint partitions, energy, counts, source/complement and SMALL partition all apply to the actual R, even when it contains SMALL. Its large balance gives strict G directly, so no H or U comparison is needed. Both low-arrival branches of the full consumer use this construction on their live proof paths.")),
                    Paragraph(Text("This is a native physical prefix construction, with no assumed replacement Legal word and no duplicated inventory engine. No claim that every old SMALL survives truncation is made. The complete dependent-telescope registration of this target remains unfinished under https://github.com/the-omega-institute/trureturing/issues/22063; the needed original-source reconstruction/equivalence bridge, actual-positive law, whole-family sensitivity and actual observational-dependence proofs are absent."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-three-negative-first-negative-arrival-free-exchange"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FirstNegativeShiftExchange.actualSource_threeNegative_firstNegative_arrival_free_exchange_full"),
                H("Full physical strict J competitor without arrival assumptions"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("The telescope is exactly that of actualSource_threeNegative_firstNegative_shift_exchange_full with ONLY harrivalpen and harrivalz removed: arbitrary k,t, hk:3<=k, physical p,y,zpen,z:Fin k, lists A,T0,T1,T2,E, P=s(p)>0, n=rho(p) LARGE, N<3*abs(s(p)), original Legal(W), p,n unused in ALL W, every occurrence of T0++T1++T2++E SMALL, y,zpen,z negative LARGE, Y=-s(y)<=P and strict C-P<sum(W)<abs(s(n)). Here x=rho(n) and W=A++[x]++T0++[y]++T1++[zpen]++T2++[z]++E. There is no crossing/q/resource/count/Z<=D premise, numerical injectivity assumption or new Legal premise.")),
                    Paragraph(Text("Put Fpen=A++[x]++T0++[y]++T1++[zpen], Rpen=T2++[z]++E and Fz=Fpen++T2++[z]. The theorem constructs literal existential physical lists V,R. In every branch it supplies Legal(V), V.Nodup, InStrip(s,C,0,V), every natural original-zero take bound (including zero and overlength), Inventory(k,t,W,V,[p,n],R), the whole-word permutation (V++R).Perm(W++[p,n]) and strict J(V)<J(W). Inventory exposes the exact full-source used and unused disjoint partitions, count/energy/source balances, zero-source complement identity and remaining-SMALL disjoint partition.")),
                    Paragraph(Text("Branch 1: if sum(Fpen)<=C-P, V=Fpen++[p,n] and R=Rpen. Existing small_weights and largeUsed_append prove largeUsed(Rpen)=1 because only z is LARGE there. The consumed prefix-pair helper yields G(V)+1=G(W), hence strict G. Branch 2: if sum(Fpen)>C-P but sum(Fz)<=C-P, V=Fz++[p,n], R=E, largeUsed(E)=0 and G(V)+2=G(W), again strict G. R can contain SMALL in either truncation; all exact physical balances use that actual R, without uniform SMALL retention or an asserted H decrease.")),
                    Paragraph(Text("Branch 3: both actual old arrivals exceed C-P, which supplies the two non-strict arrival premises of the unchanged rich shift theorem. R=[x,y]. The output retains explicit L01.Perm(T0++T1), L2.Perm(T2), LE.Perm(E), L=L01++[zpen]++L2++[z]++LE, V=A++[p,n]++L and (L++[y]).Perm(T0++[y]++T1++[zpen]++T2++[z]++E). Every occurrence of S=T0++T1++T2++E lies in L; returned x,y are absent from V, zpen,z are present, and every old SMALL including those in A is retained. This branch has G(V)=G(W), U(V)=U(W), remainingSmall(V)=remainingSmall(W), H(V)+3^abs(s(x))+3^abs(s(y))=H(W)+3^abs(s(p))+3^abs(s(n)), and strict H(V)<H(W). It also gives sum(V)=e0=sum(W)-s(y)-s(p), 0<e0<C and remainingMass(s,V)=-e0. The theorem's explicit disjunction distinguishes all three branches.")),
                    Paragraph(Text("At a genuine GLOBAL J minimum W over all Legal physical words for these same k,t, assume all source hypotheses above except Y<=P. If Y<=P held, instantiate the arrival-free theorem with the exact same p,y,zpen,z,A,T0,T1,T2,E. Its witness V is Legal and has J(V)<J(W), contradicting the global condition that J(W)<=J(V) for every Legal V. Linear order therefore gives P<Y for this native three-negative source configuration. This is a necessary exclusion of the Y<=P region at a global minimum; it supplies neither a competitor in the remaining Y>P region nor full Circle C3.1. No extra named global-minimum wrapper is retained.")),
                    Paragraph(Text("The faithful audit target is this entire original dependent telescope and its existential branch-sensitive output, not a fixed finite scalar profile. A DependentFamily realization would need exact source reconstruction and an equivalence to its Law, an actual-positive law, whole-family interventions changing each enrolled readout with other roles and anchors fixed, and actual observational dependence. No such complete proofs are supplied. Registration remains unfinished under https://github.com/the-omega-institute/trureturing/issues/22063; no finite-template, uncompiled Reg or bind-only audit wrapper is retained."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-three-negative-even-half-arrival-free"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FirstNegativeShiftExchange.actualSource_threeNegative_even_half_arrival_free_exchange_full"),
                H("Actual even half, fresh or in the terminal SMALL batch"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Keep the same native physical source and original Legal W=A++[x]++T0++[y]++T1++[zpen]++T2++[z]++E, with p,n unused in all W, all T0,T1,T2,E SMALL, and y,zpen,z negative LARGE. Put P=s(p)>0, D=abs(s(n)), r=s(x)=2P-D, B=C-P, Y=-s(y) and h=sum(W). Assume B<h<D, Y>P, Y even and r<=Y+1, equivalently Y>=r-1. The actual inverse physical label is b=rho inverse(y), with the cyclic seam included. Its required status is b unused in all W OR b in terminal E. No replacement Legal, favorable reordered prefixes, additional arrival, endpoint or capacity premise is present.")),
                    Paragraph(Text("The exact source-cycle equation at b is 2s(b)-s(y)=N times its wrap indicator. The negative wrapped branch contradicts s(y)<0; the positive wrapped branch gives odd Y since N is odd. Even Y therefore forces 2s(b)=-Y and s(b)=-mu where mu=Y/2, 0<mu<Q. This is an actual negative SMALL occurrence, with no numerical-source injectivity assumption. For odd Y the positive wrapped branch instead gives 2s(b)=N-Y and b positive LARGE. The parity premise cannot be removed.")),
                    Paragraph(Text("Use the same actual Fpen,Fz,Rpen as the arrival-free first-negative theorem. If sum(Fpen)<=B, literal V=Fpen++[p,n], R=Rpen drops G by one. Otherwise if sum(Fz)<=B, literal V=Fz++[p,n], R=E drops G by two. Both calls reuse actualSource_prefix_pair_truncation and provide ordinary Inventory W V [p,n] R. SMALL retention and consuming b are not promised in these truncation branches. Every branch gives Legal(V), physical Nodup, InStrip from zero, all natural take bounds and strict J descent.")),
                    Paragraph(Text("In the remaining branch both actual old arrivals exceed B. Let Extra=[] and Efinal=E.erase(b) when b is in E; otherwise Extra=[b] and Efinal=E. The physical erase permutation proves ([b]++Efinal).Perm(E++Extra). Nodup of W++Extra follows from original Nodup and fresh b when Extra is nonempty. This appended baseline need not be Legal. Set delta=Y+s(b)-P=mu-P<0. Since r=4P-N and N=2C+1, even Y>=r-1 gives C+1+mu-2P>=0. Integer old arrivals>B imply their translated arrivals are nonnegative; each old departure is at least its negative-step arrival. All four translated upper bounds follow from delta<0 and original legality. The literal p,n gates are unchanged: original a0+r<=C and D<P<r imply a0+P and a0+P-D lie in the strip.")),
                    Paragraph(Text("The first complete SMALL batch is T0++T1++[b], from a0+P-D to d1+delta. T2 goes from a1+delta to d2+delta; Efinal goes from a2+delta to e=h+Y+sum(Extra)-P. These are exact full-word identities. Every opposite SMALL pair has difference <=2Q-2<C, so exists_order_between orders all three complete batches. The same private physical engine also proves the original rich Y<=P theorem with F=[], Efinal=E and Extra=[]; its public strict-interior conclusion is unchanged. The literal rich competitor is V=A++[p,n]++L01++[zpen]++L2++[z]++LE, with L01.Perm(T0++T1++[b]), L2.Perm(T2) and LE.Perm(Efinal). It retains all old SMALL, zpen,z and A; x,y are absent. Equal-valued physical labels remain distinct.")),
                    Paragraph(Text("For fresh b, Extra=[b], e=h+mu-P lies in [0,C). The lower endpoint may be zero at Y=r-1 and is allowed by Legal. The exact physical permutation is (V++[x,y]).Perm(W++[p,n,b]); G(V)=G(W), U(V)+1=U(W), and remainingSmall(V)=remainingSmall(W) minus {b}. Existing Inventory is specialized to LARGE insertions, so the theorem gives Inventory (W++[b]) V [p,n] [x,y], together with ORIGINAL-W used and unused disjoint partitions for the true inserted list [p,n,b]. It does not assert the false Inventory W V [p,n,b] [x,y], nor Legal(W++[b]). For terminal b, Extra=[], Efinal=E.erase(b), e=h+Y-P is strictly inside (0,C), ordinary Inventory W V [p,n] [x,y] applies, U(V)=U(W) and remainingSmall is equal. Exactly one physical b is moved, with no loss or duplication.")),
                    Paragraph(Text("In both rich cases H(V)+3^abs(s(x))+3^abs(s(y))=H(W)+3^abs(s(p))+3^abs(s(n)). Extra has zero LARGE weight and energy; native geometry gives 3^P+3^D<3^r, hence strict H and J descent. The complement identity is remainingMass(V)=-e for the full physical source. At a genuine global J minimum over all zero-start Legal words, the theorem contradicts either available status. Under its even Y>P and Y>=r-1 source hypotheses, b must therefore already be used and lie outside terminal E. It may lie in A,T0,T1 or T2; no stronger placement is asserted. This minimum consequence adds no named specialization.")),
                    Paragraph(Text("Four-slot registration remains unfinished under https://github.com/the-omega-institute/trureturing/issues/22063. The audit target is the whole dependent source telescope, the two physical half statuses, the truncated branches and the branch-sensitive physical outputs. DependentFamily.realize and its enrollment do not supply exact source reconstruction and equivalence to an enrolled Law, whole-family variation, sensitivity with the other roles and anchors fixed, or actual observational dependence. These evidence obligations remain absent; no finite catalog or declared_validated registration is claimed."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-odd-parent-uniform-prefix"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FirstNegativeShiftExchange.actualSource_odd_parent_uniform_prefix_exchange"),
                H("An odd first negative supplies a uniform three-LARGE prefix competitor"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("This result uses a GENERAL actual Legal word W=F++[y]++R; it does not require three SMALL batches, a blocking endpoint or any last-negative arrival. Assume native expanding positive p, n=rho(p) LARGE, p,n unused in all W, odd Y=-s(y)>P, actual b=rho inverse(y) unused in all W, largeUsed(R)<=2 and 3Y>=6P-N. The inverse source-cycle proof gives L=s(b)=(N-Y)/2, Q<=L<P, so p,n,b are three distinct LARGE physical labels. The literal competitor is V=(F++[y])++[p,n,b], returning the ENTIRE actual R including its SMALL occurrences.")),
                    Paragraph(Text("Let v=sum(F++[y]) and d=P-D>0. The original literal y gate gives 0<=v and v+Y<=C, hence v<=C-Y<C-P automatically. Thus v+P and v+P-D=v+d lie in the strip. Since N=2C+1, the uniform threshold gives 2v+2d<=2C-2Y+2d<=Y-1. Together with 2L=N-Y this proves v+d+L<=C. All lower gates follow from v>=0, d>0 and L>0. The old prefix is preserved literally; inStrip_append verifies every new prefix from original zero, including zero and overlength takes. No separate measured low-valley premise or replacement Legal premise is assumed.")),
                    Paragraph(Text("The output includes Legal, physical Nodup, InStrip, all natural take bounds, Inventory W V [p,n,b] R and the physical whole-word permutation. Its exact large balance is G(V)+3=G(W)+largeUsed(R). The return bound <=2 therefore gives strict G and J descent, with all source, energy, count, complement and remaining-SMALL balances supplied by ordinary Inventory. The uniform threshold covers Y>=r and can also hold below r; it is a sufficient condition, not a claimed necessary boundary.")),
                    Paragraph(Text("For the actual three-negative word above, set F=A++[x]++T0 and R=T1++[zpen]++T2++[z]++E. The SMALL weight identity gives exactly two returned LARGE. The odd inverse parent is positive LARGE and L<P<r, so it differs from x and from all three negative occurrences, and cannot belong to the SMALL batches. Consequently b lies in W if and only if it lies in A. At a genuine global J minimum, odd Y>P and 3Y>=6P-N force b in A by this prefix competitor. This necessary placement leaves relocation from A and the remaining odd threshold region open, and does not prove full C3.1. No separate named minimum wrapper is retained.")),
                    Paragraph(Text("Registration for this full arbitrary-F,R dependent telescope remains unfinished under https://github.com/the-omega-institute/trureturing/issues/22063. A faithful DependentFamily audit needs the original-source reconstruction/equivalence bridge, actual-positive law, whole-family variation and fixed-other-role sensitivity, and actual observational-dependence evidence. Neither a finite scalar checker nor the existence of the enrollment API supplies those proofs."))),
                DescribeRole.Theorem)), []));
}
